// Go 1.27.1 strings/replace_test.go TestReplacer: 49 selected generic Replace rows.
// Alternative optimized engines and the separate WriteString assertions are not claimed.
using TypeScript.Scanner;

namespace LanguageServices.Checks;
public static class GenericReplacerChecks
{
    public static int RunAll()
    {
        foreach (var row in Rows)
        {
            var actual = GoGenericReplacer.Make(Slice<ByteStringValue>.FromArray(row.Pairs)).Replace(row.Input);
            if (!actual.EqualsValue(row.Expected))
                throw new InvalidOperationException("Original generic replacement differs: " + Convert.ToHexString(row.Input.ByteSpan));
        }

        return 1; // One selected assertion channel, not a complete original function.
    }

    private static ByteStringValue Value(string hex) => ByteStringValue.FromView(ByteStringView.FromOwnedBytes(Convert.FromHexString(hex)));
